import sys
sys.path.insert(0, 'src')
import service
from unittest.mock import patch
from itertools import product

original = service.price_cents
checks = 0
for unit, quantity, percent, cap in product([0, 1, 101, 10**25], [0, 1, 3], [0, 1, 33, 99, 100], [0, 1, 25, 10**30]):
    rule = {'percent': percent, 'cap_cents': cap}
    snapshot = dict(rule)
    with patch.object(service, 'price_cents', wraps=original) as counted:
        result = service.discounted_price(unit, quantity, rule)
        counted.assert_called_once_with(unit, quantity)
    total = unit * quantity
    assert result == total - min(total * percent // 100, cap)
    assert type(result) is int
    assert rule == snapshot
    assert original(unit, quantity) == total
    checks += 1
assert service.discounted_price(101, 1, {'percent':33, 'cap_cents':100}) == 68
with patch.object(service, 'price_cents', return_value=103) as counted:
    assert service.discounted_price(1, 1, {'percent':50, 'cap_cents':100}) == 52
    counted.assert_called_once_with(1, 1)

invalid_rules = [None, [], 'rule', {}, {'percent':10}, {'cap_cents':10},
                 {'percent':10, 'cap_cents':10, 'extra':0}]
for bad in [True, False, -1, 101, 10.5, '10', None, [], object()]:
    invalid_rules.append({'percent':bad, 'cap_cents':10})
for bad in [True, False, -1, 10.5, '10', None, [], object()]:
    invalid_rules.append({'percent':10, 'cap_cents':bad})
for rule in invalid_rules:
    try:
        service.discounted_price(100, 2, rule)
    except ValueError:
        checks += 1
    else:
        raise AssertionError(('invalid rule accepted', rule))
for bad in [True, False, -1, 1.0, '1', None, [], object()]:
    for pair in [(bad, 1), (1, bad)]:
        for function, args in [(original, pair), (service.discounted_price, (*pair, {'percent':10, 'cap_cents':100}))]:
            try:
                function(*args)
            except ValueError:
                checks += 1
            else:
                raise AssertionError(('invalid price accepted', pair))
print('PASS:', checks, 'price and discount probes; exactly-once reuse, reused result, integer floor, bounds, cap, validation, and existing standalone behavior verified')
