def list_active(rows, page, size):
    if isinstance(page, bool) or not isinstance(page, int) or page < 0:
        raise ValueError('page must be an integer >= 0')
    if isinstance(size, bool) or not isinstance(size, int) or size < 1:
        raise ValueError('size must be an integer >= 1')
    active_rows = [row for row in rows if row['active'] is True]
    return active_rows[page * size:(page + 1) * size]

def price_cents(unit_cents, quantity):
    if type(unit_cents) is not int or type(quantity) is not int or min(unit_cents, quantity) < 0:
        raise ValueError('invalid price')
    return unit_cents * quantity


def discounted_price(unit_cents, quantity, rule):
    if not isinstance(rule, dict) or set(rule) != {'percent', 'cap_cents'}:
        raise ValueError('invalid discount rule')
    percent, cap_cents = rule['percent'], rule['cap_cents']
    if (isinstance(percent, bool) or not isinstance(percent, int)
            or not 0 <= percent <= 100
            or isinstance(cap_cents, bool) or not isinstance(cap_cents, int)
            or cap_cents < 0):
        raise ValueError('invalid discount rule')
    total = price_cents(unit_cents, quantity)
    return total - min(total * percent // 100, cap_cents)

